// Reid Energy Solutions - pre-call lookup, called by Retell the moment a call
// lands. This endpoint serves TWO callers; detect which, because both the
// payload shape AND the required response shape differ.
//
//   PRE-CALL WEBHOOK  fires before the call connects, set on the phone number.
//     in : { event:"call_inbound", call_inbound:{ agent_id, from_number, to_number } }
//     out: { call_inbound: { dynamic_variables: { ... } } }   <- anything else is
//          silently ignored by Retell. 10s budget, 3 retries, then it gives up.
//
//   CUSTOM FUNCTION   fires mid-call if the agent is ever given this as a tool.
//     in : { call:{ agent_id, from_number, ... }, args:{ phone } }
//     out: flat JSON, read by the model.
//
// The caller's number must come from the phone network, not from the model.
// body.args.phone is whatever the LLM decided to send: it mis-hears digits,
// drops the country code, or sends the literal string "{{from_number}}".
// SKILL.md 4.3 flags reading from_number instead as the fix for new builds.

const body = $input.first().json.body || {};
const inbound = body.call_inbound || null;
const is_precall = String(body.event || '') === 'call_inbound' || !!inbound;

// In pre-call mode the call object IS call_inbound; mid-call it is body.call.
const call = inbound || body.call || {};
const args = body.args || {};

function norm(p) {
  let s = String(p == null ? '' : p).replace(/[^\d+]/g, '');
  if (!s) return '';
  s = s.replace(/^\++/, '+');
  if (s.charAt(0) === '0') return '+44' + s.slice(1);   // UK national -> E.164
  if (s.charAt(0) !== '+') return '+' + s;
  return s;
}

// Reid's agent is inbound only, but keep the direction check: on an OUTBOUND
// call from_number is the agent's own caller ID, and searching on it finds the
// client's own contact record or creates junk.
const direction = is_precall ? 'inbound' : String(call.direction || 'inbound').toLowerCase();
const metaNumber = direction === 'outbound' ? call.to_number : call.from_number;

// args.phone is the LAST resort: web calls carry no number, and a withheld
// number arrives empty - which is a legitimate state, not an error.
let phone = norm(metaNumber);
let phone_source = phone ? ('call.' + (direction === 'outbound' ? 'to_number' : 'from_number')) : '';
if (!phone) {
  phone = norm(args.phone);
  phone_source = phone ? 'args.phone' : 'none';
}

// ---- office_status --------------------------------------------------------
// The prompt reads {{office_status}} to decide whether it may offer a transfer
// to Ian. It is worked out HERE, before any branching, so every response path -
// including "agent not mapped" and "no caller number" - still carries it.
//
// Reid is open Monday to Friday, 8am to 5pm, Europe/London. Anything else is
// closed. The prompt's own fallback also defaults to closed, so the agent can
// never promise a transfer it cannot make.
const OPEN_DAYS = [1, 2, 3, 4, 5];       // Mon-Fri, 0 = Sunday
const OPEN_FROM_MIN = 8 * 60;            // 08:00
const OPEN_UNTIL_MIN = 17 * 60;          // 17:00

// Dates the office is shut regardless of weekday - NI bank holidays, Christmas
// shutdown. 'YYYY-MM-DD', London dates. Left empty until the client supplies
// them; a guessed list is worse than the weekday rule alone.
const CLOSED_DATES = [];

function lastSundayUTC(year, monthIndex) {
  // Last day of the month at 01:00 UTC, walked back to the Sunday.
  const d = new Date(Date.UTC(year, monthIndex + 1, 0, 1, 0, 0));
  d.setUTCDate(d.getUTCDate() - d.getUTCDay());
  return d;
}

function inBST(d) {
  const y = d.getUTCFullYear();
  return d >= lastSundayUTC(y, 2) && d < lastSundayUTC(y, 9);   // last Sun Mar -> last Sun Oct
}

function londonParts(d) {
  try {
    const parts = {};
    new Intl.DateTimeFormat('en-GB', {
      timeZone: 'Europe/London',
      weekday: 'short', year: 'numeric', month: '2-digit', day: '2-digit',
      hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
    }).formatToParts(d).forEach(function (p) { parts[p.type] = p.value; });

    const wd = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 }[parts.weekday];
    if (wd === undefined) throw new Error('no weekday');
    const hour = parseInt(parts.hour, 10) % 24;             // some builds report 24:00
    return {
      day: wd,
      minutes: hour * 60 + parseInt(parts.minute, 10),
      date: parts.year + '-' + parts.month + '-' + parts.day,
    };
  } catch (e) {
    // Fallback for a container built without full ICU data: the UK is UTC,
    // plus one hour during British Summer Time.
    const local = new Date(d.getTime() + (inBST(d) ? 60 : 0) * 60000);
    const mm = String(local.getUTCMonth() + 1).padStart(2, '0');
    const dd = String(local.getUTCDate()).padStart(2, '0');
    return {
      day: local.getUTCDay(),
      minutes: local.getUTCHours() * 60 + local.getUTCMinutes(),
      date: local.getUTCFullYear() + '-' + mm + '-' + dd,
    };
  }
}

