let london_time = '';
try {
  const p = londonParts(new Date());
  london_time = p.date + ' ' + String(Math.floor(p.minutes / 60)).padStart(2, '0') + ':' +
                String(p.minutes % 60).padStart(2, '0');
  if (CLOSED_DATES.indexOf(p.date) === -1 &&
      OPEN_DAYS.indexOf(p.day) !== -1 &&
      p.minutes >= OPEN_FROM_MIN && p.minutes < OPEN_UNTIL_MIN) {
    office_status = 'open';
  }
} catch (e) {
  office_status = 'closed';   // never guess open
}

