  is_precall: is_precall,
  agent_id: String(call.agent_id || body.agent_id || ''),
  call_id: String(call.call_id || ''),
  direction: direction,
  phone: phone,
  phone_source: phone_source,
  office_status: office_status,
  london_time: london_time,
} }];

// Both lookups run with alwaysOutputData, so "no match" arrives as an empty
// object rather than as a stopped chain. Decide here, once, whether we can
// actually call GHL - and if not, say exactly why.
//
// office_status rides through untouched: it is already decided and it must
// reach the agent even when the CRM lookup cannot run.

const req = $('Extract Args').first().json;

let location_id = '';
try { location_id = ($('Agent -> Location').first().json || {}).location_id || ''; } catch (e) {}

let token = '';
try { token = ($('Location -> Token').first().json || {}).access_token || ''; } catch (e) {}

let ok = true;
let reason = '';
if (!location_id) {
  ok = false;
  reason = 'agent_not_mapped';        // add the row to xQoeAdJAp7DTlnkc
} else if (!token) {
  ok = false;
  reason = 'no_token_for_location';   // marketplace app not installed on this sub-account
} else if (!req.phone) {
  ok = false;
  reason = 'no_caller_number';        // withheld number, or a web call
}

return [{ json: Object.assign({}, req, { location_id: location_id, token: token, ok: ok, reason: reason }) }];

// Pre-call must answer { call_inbound: { dynamic_variables: {...} } }. Retell
// ignores anything else without raising an error. The mid-call shape is the
// flat found / contact_id / name / email / tags object, kept for parity with
// the shared workflow so this endpoint can also back a custom function.
//
// The Reid prompt reads exactly two of these by name - {{first_name}} and
// {{property_address}} - and applies the presence principle: a value that is
// there is real, an empty one means nobody has captured it, so ask. The
// customer_* variables are sent so a later prompt revision can use them without
// touching this workflow; nothing speaks them today.
//
// office_status was removed on 2026-09-16. The agent works the office hours out
// itself from the clock, with its Retell timezone set to Europe/London, so this
// workflow no longer has to decide them - and cannot get them wrong.

const cfg = $('Config OK?').first().json;
const raw = $input.first().json || {};

// /contacts/search/duplicate answers { contact: {...} }; a 404/401 arrives here
// as an { error: ... } object because onError is continueRegularOutput.
const c = raw.contact || (raw.id ? raw : null);
const lookup_failed = !!raw.error;

const name = c ? (c.contactName || [c.firstName, c.lastName].filter(Boolean).join(' ') || '') : '';
const first_name = c ? String(c.firstName || String(name).split(' ')[0] || '').trim() : '';
const email = c ? (c.email || '') : '';
const phone = c ? (c.phone || '') : '';
const tags = c ? (c.tags || []).join(', ') : '';

// Address and postcode are STANDARD contact fields, not custom ones, so they
// never appear in the customFields loop below. The website forms write them,
// so most repeat callers already have them.
let address = c ? (c.address1 || '') : '';
let post_code = c ? (c.postalCode || '') : '';
