return [{ json: withResolved(Object.assign({
  found: !!c, is_existing: !!c,
  contact_id: c ? (c.id || '') : '',
  first_name: first_name,
  name: name,
  email: email,
  phone: phone,
  tags: tags,
  address: address,
  post_code: post_code,
  reason: reason,
  phone_source: cfg.phone_source,
}, extras)) }];

// Retell waits on this HTTP response. If the workflow ends without one, the
// pre-call webhook retries 3x and then starts the call with no variables at all
// - and the agent then speaks the literal "{{office_status}}" to the caller. So
// a config problem must still answer, as an unknown caller, which is a state
// the prompt already handles.
//
