  // never renders a literal {{first_name}} to the caller.
  return [{ json: {
    call_inbound: {
      dynamic_variables: {
        first_name: '',
        property_address: '',
        customer_name: '',
        customer_email: '',
        customer_phone: '',
        customer_tags: '',
        customer_address: '',
        customer_post_code: '',
      },
      metadata: {
        contact_id: '',
        lookup_reason: cfg.reason || 'config_error',
        london_time: String(cfg.london_time || ''),
      },
    },
  } }];
}

