// ---- address fallback -----------------------------------------------------
// Plenty of accounts capture the address in a custom field rather than the
// standard one - installation_address, site_address, property_address. Reid's
// agent checks the caller's area on every new-install call, so already holding
// the address is worth real seconds. "email_address" is excluded deliberately:
// it matches /address/ and is not one.
function firstMatch(rx, exclude) {
  const keys = Object.keys(extras).sort();          // stable, not hash order
  for (let i = 0; i < keys.length; i++) {
    const k = keys[i];
    if (exclude && exclude.test(k)) continue;
    if (rx.test(k) && String(extras[k]).trim()) return String(extras[k]).trim();
  }
  return '';
}
if (!address)   address   = firstMatch(/address|premises|property_location/, /email|ip_address/);
if (!post_code) post_code = firstMatch(/post_?code|postal/, null);

// Keys the prompt may read by name. Retell leaves an UNSENT variable in the
// prompt as the literal text "{{first_name}}", which the agent then speaks to
// the caller - so every one of these must exist on every call, as an empty
// string when we have nothing.
const REQUIRED = ['customer_address', 'customer_post_code'];
REQUIRED.forEach(function (k) { if (typeof extras[k] !== 'string') extras[k] = ''; });

// extras is merged OVER the base variables, so the two the fallback above
// resolved have to be written back afterwards - otherwise a blank placeholder
// from REQUIRED wins and the agent asks for an address we are holding.
function withResolved(vars) {
  if (address) vars.customer_address = String(address);
  if (post_code) vars.customer_post_code = String(post_code);

  // {{property_address}} is the variable the Reid prompt actually reads. It is the
  // address and the postcode as ONE string, because the agent says it back to the
  // caller as one line: "so that's still eighty-two Manse Road, Carryduff, BT8 8AE".
  // Always present, even when empty - an unsent variable renders as the literal
  // "{{property_address}}" and the agent speaks it.
  vars.property_address = [vars.customer_address, vars.customer_post_code]
    .filter(function (s) { return s && String(s).trim(); })
    .join(', ');
  return vars;
}

if (cfg.is_precall) {
  // EVERY dynamic variable must be a string. A null or a number makes Retell
  // drop the whole variable, and the prompt then speaks the literal
  // "{{first_name}}" to the caller.
  return [{ json: {
    call_inbound: {
      dynamic_variables: withResolved(Object.assign({
        first_name: String(first_name),
        customer_name: String(name),
        customer_email: String(email),
        customer_phone: String(phone),
        customer_tags: String(tags),
        customer_address: String(address),
        customer_post_code: String(post_code),
      }, extras)),
      metadata: {
        contact_id: String(c ? (c.id || '') : ''),
        lookup_reason: reason,
        london_time: String(cfg.london_time || ''),
      },
    },
  } }];
}

return [{ json: withResolved(Object.assign({
  found: !!c, is_existing: !!c,
  contact_id: c ? (c.id || '') : '',
  first_name: first_name,
  name: name,
  email: email,
  phone: phone,
  tags: tags,
  address: address,
  post_code: post_code,
  reason: reason,
  phone_source: cfg.phone_source,
}, extras)) }];

// Retell waits on this HTTP response. If the workflow ends without one, the
// pre-call webhook retries 3x and then starts the call with no variables at all
// - and the agent then speaks the literal "{{office_status}}" to the caller. So
// a config problem must still answer, as an unknown caller, which is a state
// the prompt already handles.
//
// office_status is the one value that is still TRUE on this path: it comes from
// the clock, not from the CRM, so a missing token or a withheld number does not
// cost the agent its transfer logic. reason is for the logs only - the agent
// never speaks it.

const cfg = $input.first().json || {};

if (cfg.is_precall) {
  // Empty strings, not omitted keys: the variables must exist so the prompt
  // never renders a literal {{first_name}} to the caller.
  return [{ json: {
    call_inbound: {
      dynamic_variables: {
        first_name: '',
        property_address: '',
        customer_name: '',
        customer_email: '',
        customer_phone: '',
        customer_tags: '',
        customer_address: '',
        customer_post_code: '',
      },
      metadata: {
        contact_id: '',
        lookup_reason: cfg.reason || 'config_error',
        london_time: String(cfg.london_time || ''),
      },
    },
  } }];
}

return [{ json: {
  found: false, is_existing: false,
  contact_id: '', first_name: '', name: '', email: '', tags: '',
  address: '', post_code: '', property_address: '',
  reason: cfg.reason || 'config_error',
  phone_source: cfg.phone_source || 'none',
} }];
